{
  "items": [
    {
      "name": "exists_lt_of_lt_csSup'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrderBot α] {s : Set α} {a : α}, a < sSup s → ∃ b ∈ s, a < b"
    },
    {
      "name": "lt_sSup_iff",
      "module_name": "Mathlib.Order.CompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : CompleteLinearOrder α] {s : Set α} {b : α}, b < sSup s ↔ ∃ a ∈ s, b < a"
    },
    {
      "name": "Real.sSup_le",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {s : Set ℝ} {a : ℝ}, (∀ x ∈ s, x ≤ a) → 0 ≤ a → sSup s ≤ a"
    },
    {
      "name": "Real.exists_isLUB",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {s : Set ℝ}, s.Nonempty → BddAbove s → ∃ x, IsLUB s x"
    },
    {
      "name": "csSup_le_iff",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLattice α] {s : Set α} {a : α},\n  BddAbove s → s.Nonempty → (sSup s ≤ a ↔ ∀ b ∈ s, b ≤ a)"
    },
    {
      "name": "Real.isLUB_sSup",
      "module_name": "Mathlib.Data.Real.Archimedean",
      "kind": "theorem",
      "type": "∀ {s : Set ℝ}, s.Nonempty → BddAbove s → IsLUB s (sSup s)"
    },
    {
      "name": "csSup_le_iff'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrderBot α] {s : Set α},\n  BddAbove s → ∀ {a : α}, sSup s ≤ a ↔ ∀ x ∈ s, x ≤ a"
    },
    {
      "name": "sup_le",
      "module_name": "Mathlib.Order.Lattice",
      "kind": "theorem",
      "type": "∀ {α : Type u} [inst : SemilatticeSup α] {a b c : α}, a ≤ c → b ≤ c → a ⊔ b ≤ c"
    }
  ]
}
